/**
 * Minimal in-process job queue: enqueue, drain, retry with backoff. Jobs never run inside a request.
 */
import { createLogger } from "@/lib/logger";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type QueuedJob = {
  id: string;
  kind: JobKind;
  runAt: IsoTimestamp;
  attempts: number;
  payload: Readonly<Record<string, unknown>>;
};

export type JobKind =
  | "digest-email"
  | "overdue-issues"
  | "webhook-delivery"
  | "usage-rollup"
  | "search-reindex"
  | "cleanup-archived"
  | "trial-expiry";

/** Attempts after which a job is dropped rather than retried again. */
const MAX_ATTEMPTS = 5;

/** How many jobs `drain()` takes in one pass when no limit is given. */
const DEFAULT_DRAIN = 25;

const logger = createLogger("job-queue");

/**
 * The queue lives in module scope: Taskflow runs one server process and the
 * scheduler is started from `instrumentation.ts`, so there is no second
 * consumer to coordinate with. Swapping this for a real broker means
 * reimplementing these four functions and nothing else.
 */
const pending: QueuedJob[] = [];

/** Idempotent on `id`: re-enqueuing a job keeps the earlier `runAt`. */
export function enqueue(job: QueuedJob): void {
  if (pending.some((queued) => queued.id === job.id)) return;
  pending.push(job);
}

/**
 * Runs everything that is due, oldest first. A handler that throws is put back
 * with an exponential delay until `MAX_ATTEMPTS`, then dropped with a log line
 * — an infinitely retrying job is worse than a lost one.
 */
export async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {
  const now = new Date().toISOString();
  const due = pending
    .filter((job) => job.runAt <= now)
    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))
    .slice(0, Math.max(0, limit));

  let completed = 0;

  for (const job of due) {
    remove(job.id);

    try {
      await runHandler(job);
      completed += 1;
    } catch (error) {
      const attempts = job.attempts + 1;

      if (attempts >= MAX_ATTEMPTS) {
        logger.error("job dropped after max attempts", {
          id: job.id,
          kind: job.kind,
          attempts,
        });
        continue;
      }

      pending.push({
        ...job,
        attempts,
        runAt: toIsoTimestamp(new Date(Date.now() + backoffMs(attempts))),
      });

      logger.warn("job retry scheduled", {
        id: job.id,
        kind: job.kind,
        attempts,
        reason: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return completed;
}

export function pendingCount(): number {
  return pending.length;
}

/** Test hook: empties the queue. Never call this from application code. */
export function resetQueue(): void {
  pending.length = 0;
}

/** 1s, 2s, 4s, 8s … capped at one minute. */
function backoffMs(attempts: number): number {
  return Math.min(60_000, 2 ** (attempts - 1) * 1_000);
}

function remove(id: string): void {
  const at = pending.findIndex((job) => job.id === id);
  if (at >= 0) pending.splice(at, 1);
}

/**
 * Dispatches one queued job to its runner. The imports are dynamic so the
 * queue module stays free of a cycle: every job module imports this one to
 * enqueue follow-up work.
 */
async function runHandler(job: QueuedJob): Promise<void> {
  const now = new Date();

  switch (job.kind) {
    case "digest-email": {
      const { runDigestEmailJob } = await import("./digest-email-job");
      await runDigestEmailJob(now);
      return;
    }
    case "overdue-issues": {
      const { runOverdueIssueJob } = await import("./overdue-issue-job");
      await runOverdueIssueJob(now);
      return;
    }
    case "webhook-delivery": {
      const { runWebhookDeliveryJob } = await import("./webhook-delivery-job");
      await runWebhookDeliveryJob(now);
      return;
    }
    case "usage-rollup": {
      const { runUsageRollupJob } = await import("./usage-rollup-job");
      await runUsageRollupJob(now);
      return;
    }
    case "search-reindex": {
      const { runSearchReindexJob } = await import("./search-reindex-job");
      const orgId = job.payload.orgId;
      if (typeof orgId !== "string") return;
      await runSearchReindexJob(orgId as Parameters<typeof runSearchReindexJob>[0]);
      return;
    }
    case "cleanup-archived": {
      const { runCleanupArchivedJob } = await import("./cleanup-archived-job");
      await runCleanupArchivedJob(now);
      return;
    }
    case "trial-expiry": {
      const { runTrialExpiryJob } = await import("./trial-expiry-job");
      await runTrialExpiryJob(now);
      return;
    }
  }
}

/**
 * Server-side flag context construction and the org-level override toggle.
 *
 * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit
 */
import { emit } from "@/lib/event-bus";
import { isEnabled, snapshotFlags } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { getFlagDefinition } from "@/config/feature-flags";
import * as orgRepo from "@/server/repositories/organization-repository";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import type { ToggleFeatureFlagInput } from "@/schemas/feature-flag";
import type { FeatureFlagSnapshot, FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/**
 * Builds the evaluation context every `isEnabled()` call needs. Both halves
 * are nullable so marketing pages — no session, no org — can still ask about
 * a flag and get the free-plan answer.
 */
export function buildFlagContext(
  actor: Actor | null,
  org: Organization | null,
): FlagContext {
  return {
    orgId: org?.id ?? actor?.orgId ?? null,
    userId: actor?.userId ?? null,
    plan: org?.plan ?? "free",
    role: actor?.role ?? null,
    overrides: org?.settings.enabledFlagOverrides,
  };
}

/**
 * The serialisable snapshot the dashboard layout hands to the client provider,
 * so `useFeatureFlag()` answers without a round trip and cannot disagree with
 * the server.
 */
export function getSnapshot(
  actor: Actor,
  org: Organization,
): FeatureFlagSnapshot {
  return snapshotFlags(buildFlagContext(actor, org));
}

/**
 * Adds or removes an org-level override. Only flags declared `overridable`
 * accept one — a flag gated purely on plan cannot be switched on by an admin,
 * which is what keeps the plan boundary meaningful.
 */
export async function toggleFlag(
  actor: Actor,
  input: ToggleFeatureFlagInput,
): Promise<Organization> {
  assertCan(actor, "org:manage_flags", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const definition = getFlagDefinition(input.flag);
  if (!definition.overridable) {
    throw new Error(`Feature "${input.flag}" cannot be overridden per org`);
  }

  const current = new Set(org.settings.enabledFlagOverrides);
  if (input.enabled) {
    current.add(input.flag);
  } else {
    current.delete(input.flag);
  }

  const updated = await orgRepo.updateOrg(input.orgId, {
    orgId: input.orgId,
    settings: { enabledFlagOverrides: [...current] },
  });

  await emit("flag.toggled", {
    ...actorEnvelope(actor),
    flag: input.flag,
    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),
  });

  return updated;
}

/**
 * Next.js instrumentation hook. Runs once per server process before any
 * request is handled — the only sanctioned place to register the event-bus
 * subscribers and start the in-process job scheduler.
 */
export async function register(): Promise<void> {
  if (process.env.NEXT_RUNTIME !== "nodejs") return;

  const { registerEventHandlers } = await import(
    "@/server/services/event-registry"
  );
  const { startScheduler } = await import("@/server/jobs/scheduler");

  registerEventHandlers();
  startScheduler();
}

